        private static void ConfigureKpiCard(
            DevExpress.XtraEditors.PanelControl card,
            System.Windows.Forms.Panel accent,
            System.Windows.Forms.Label value,
            System.Windows.Forms.Label title,
            System.Windows.Forms.Panel badge,
            System.Windows.Forms.Label icon,
            string caption,
            string iconText,
            string accentHex)
        {
            card.BorderStyle =
                DevExpress.XtraEditors.Controls.BorderStyles.Simple;

            card.Dock =
                System.Windows.Forms.DockStyle.Fill;

            card.Margin =
                new System.Windows.Forms.Padding(6);

            card.Padding =
                new System.Windows.Forms.Padding(0);

            card.Controls.Add(accent);
            card.Controls.Add(value);
            card.Controls.Add(title);
            card.Controls.Add(badge);

            System.Drawing.Color accentColor =
                System.Drawing.ColorTranslator.FromHtml(accentHex);

            bool isDarkSkin =
                Cost.Accounting.Automation.WinFormsApp.Utils.SkinTheme.IsDarkSkin;

            System.Drawing.Color displayAccent =
                isDarkSkin
                    ? Cost.Accounting.Automation.WinFormsApp.Utils.SkinTheme.Blend(
                        accentColor,
                        System.Drawing.Color.White,
                        0.35F)
                    : accentColor;

            accent.Dock =
                System.Windows.Forms.DockStyle.Left;

            accent.Width =
                4;

            accent.BackColor =
                displayAccent;

            badge.Size =
                new System.Drawing.Size(
                    30,
                    30);

            badge.BackColor =
                accentColor;

            badge.Controls.Add(icon);

            icon.Dock =
                System.Windows.Forms.DockStyle.Fill;

            icon.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    13F,
                    System.Drawing.FontStyle.Bold);

            icon.ForeColor =
                System.Drawing.Color.White;

            icon.Text =
                iconText;

            icon.TextAlign =
                System.Drawing.ContentAlignment.MiddleCenter;

            value.AutoSize =
                false;

            value.Text =
                "-";

            value.TextAlign =
                System.Drawing.ContentAlignment.MiddleLeft;

            value.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    13F,
                    System.Drawing.FontStyle.Bold);

            value.ForeColor =
                isDarkSkin
                    ? System.Drawing.Color.FromArgb(232, 236, 243)
                    : System.Drawing.Color.FromArgb(32, 32, 32);

            title.AutoSize =
                false;

            title.Text =
                caption;

            title.TextAlign =
                System.Drawing.ContentAlignment.MiddleLeft;

            title.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    8F,
                    System.Drawing.FontStyle.Bold);

            title.ForeColor =
                displayAccent;

            card.Resize += (_, _) =>
            {
                badge.Location =
                    new System.Drawing.Point(
                        card.ClientSize.Width - badge.Width - 4,
                        4);

                int textWidth =
                    System.Math.Max(
                        40,
                        badge.Left - 16);

                value.Location =
                    new System.Drawing.Point(
                        8,
                        4);

                value.Width =
                    textWidth;

                value.Height =
                    System.Math.Max(
                        22,
                        card.ClientSize.Height / 2);

                title.Location =
                    new System.Drawing.Point(
                        8,
                        value.Bottom + 1);

                title.Width =
                    textWidth;
            };
        }

        private static void ConfigureTablePanel(
            DevExpress.XtraEditors.PanelControl panel,
            System.Windows.Forms.Label title,
            DevExpress.XtraGrid.GridControl grid,
            DevExpress.XtraGrid.Views.Grid.GridView view,
            string caption)
        {
            panel.BorderStyle =
                DevExpress.XtraEditors.Controls.BorderStyles.Simple;

            panel.Dock =
                System.Windows.Forms.DockStyle.Fill;

            panel.Margin =
                new System.Windows.Forms.Padding(8);

            panel.Padding =
                new System.Windows.Forms.Padding(
                    12,
                    40,
                    12,
                    6);

            panel.Controls.Add(grid);
            panel.Controls.Add(title);

            title.AutoSize =
                false;

            title.Location =
                new System.Drawing.Point(14, 10);

            title.Size =
                new System.Drawing.Size(350, 24);

            title.Text =
                caption;

            title.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    10F,
                    System.Drawing.FontStyle.Bold);

            view.GridControl =
                grid;

            grid.MainView =
                view;

            grid.Dock =
                System.Windows.Forms.DockStyle.Fill;

            view.OptionsBehavior.Editable =
                false;

            view.OptionsView.ShowGroupPanel =
                false;

            view.OptionsView.ShowAutoFilterRow =
                false;

            view.OptionsView.ShowIndicator =
                false;

            view.OptionsView.EnableAppearanceEvenRow =
                true;

            view.OptionsView.EnableAppearanceOddRow =
                true;
        }

        private static void ConfigureChartPanel(
            DevExpress.XtraEditors.PanelControl panel,
            System.Windows.Forms.Label title,
            DevExpress.XtraCharts.ChartControl chart,
            string caption)
        {
            // Grafik panellerini de belirgin kartlar haline getirip aralarına boşluk ekledik
            panel.BorderStyle =
                DevExpress.XtraEditors.Controls.BorderStyles.Simple;

            panel.Dock =
                System.Windows.Forms.DockStyle.Fill;

            panel.Margin =
                new System.Windows.Forms.Padding(8);

            panel.Padding =
                new System.Windows.Forms.Padding(
                    12,
                    40,
                    12,
                    12);

            panel.Controls.Add(chart);
            panel.Controls.Add(title);

            title.AutoSize =
                false;

            title.Location =
                new System.Drawing.Point(14, 10);

            title.Size =
                new System.Drawing.Size(350, 24);

            title.Text =
                caption;

            title.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    10F,
                    System.Drawing.FontStyle.Bold);

            chart.Dock =
                System.Windows.Forms.DockStyle.Fill;

            chart.BorderOptions.Visibility =
                DevExpress.Utils.DefaultBoolean.False;

            chart.Legend.EnableAntialiasing =
                DevExpress.Utils.DefaultBoolean.True;
        }
